"use client";

import { useState } from "react";
import { useSubmit } from "@/lib/api";
import Select from "@/components/finance/Select";
import Input from "@/components/finance/Input";
import Button from "@/components/finance/Button";
import { TRANSACTION_TYPES, TRANSACTION_CATEGORIES } from "@/lib/types";

const TransactionForm = ({ onSaved }: { onSaved: () => void }) => {
  const [account, setAccount] = useState("");
  const [date, setDate] = useState("");
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [type, setType] = useState("");
  const [category, setCategory] = useState("");

  const submit = useSubmit();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = {
      entity: "transaction",
      account,
      date,
      description,
      amount,
      type,
      category,
    };
    await submit("/api/finance/import/manual", payload);
    onSaved();
  };

  return (
    <form onSubmit={handleSubmit}>
      <Select
        label="Account"
        value={account}
        onChange={(e) => setAccount(e.target.value)}
      />
      <Input
        label="Date"
        type="date"
        value={date}
        onChange={(e) => setDate(e.target.value)}
      />
      <Input
        label="Description"
        value={description}
        onChange={(e) => setDescription(e.target.value)}
      />
      <Input
        label="Amount"
        type="number"
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
      />
      <Select
        label="Type"
        value={type}
        onChange={(e) => setType(e.target.value)}
        options={TRANSACTION_TYPES}
      />
      <Select
        label="Category"
        value={category}
        onChange={(e) => setCategory(e.target.value)}
        options={TRANSACTION_CATEGORIES}
      />
      <Button type="submit">Submit</Button>
    </form>
  );
};

export default TransactionForm;
